// Pack Pass emotes and portrait frames (site only). Art is generated by scripts/site/emotes/ from the
// Latch & Friends reference spec into public/site/img/pass/. Emotes unlock while a plan's perks apply;
// the Legendary emotes are for Ultimate only. Frames show around a member's icon in chat, on the
// leaderboard, in the header and on the Rewards page. Trevor (Nov 25): Plus gets the frame only; emotes
// start at Pro, so each tier adds something.
import { ICONS } from "../../lib/cardbit-levels";

export const PASS_EMOTES = [
  { id: "hype", name: "Hype", ultimate: false },
  { id: "love", name: "Love", ultimate: false },
  { id: "lol", name: "LOL", ultimate: false },
  { id: "shock", name: "Shocked", ultimate: false },
  { id: "legend", name: "Legendary", ultimate: true },
] as const;
export type PassTierId = "plus" | "pro" | "ultimate";
const TIER_IDS: readonly string[] = ["plus", "pro", "ultimate"];
export const isPassTier = (t: unknown): t is PassTierId => typeof t === "string" && TIER_IDS.includes(t);

type PassIcon = { id: string; character: string; emote: string; ultimate: boolean };
const LEGACY_SUFFIX = "-club"; // earlier animated icons, now shown as the Hype emote
export const PASS_ICONS: PassIcon[] = ICONS.flatMap((i) => PASS_EMOTES.map((e) => ({ id: `${i.id}-${e.id}`, character: i.id, emote: e.id, ultimate: e.ultimate })));
const BY_ID = new Map<string, PassIcon>(PASS_ICONS.map((p) => [p.id, p]));
for (const i of ICONS) BY_ID.set(i.id + LEGACY_SUFFIX, BY_ID.get(`${i.id}-hype`)!);

export const passIcon = (id: unknown) => (typeof id === "string" ? BY_ID.get(id) ?? null : null);
export const isPassIcon = (id: unknown): id is string => passIcon(id) !== null;
/** Whether a member on this tier (null = no plan) may use the icon. Regular icons aren't judged here. */
export const passIconAllowed = (id: unknown, tier: string | null | undefined) => {
  const p = passIcon(id);
  return Boolean(p && (tier === "pro" || tier === "ultimate") && (!p.ultimate || tier === "ultimate"));
};
const emoteUrl = (p: PassIcon) => `/site/img/pass/emotes/${p.character}-${p.emote}.svg`;
export const PASS_ICON_URLS: Record<string, string> = Object.fromEntries([...BY_ID].map(([id, p]) => [id, emoteUrl(p)]));
export const PASS_FRAME_URLS: Record<PassTierId, string> = {
  plus: "/site/img/pass/frames/plus.svg",
  pro: "/site/img/pass/frames/pro.svg",
  ultimate: "/site/img/pass/frames/ultimate.svg",
};
/** Plate-less frames for avatars under 48px (chat, header badge, leaderboard rows). */
export const PASS_FRAME_SM_URLS: Record<PassTierId, string> = {
  plus: "/site/img/pass/frames/plus-sm.svg",
  pro: "/site/img/pass/frames/pro-sm.svg",
  ultimate: "/site/img/pass/frames/ultimate-sm.svg",
};
/** Browser config for public/site/js/cardbit-site-pass.js. */
export const passClientJson = () => JSON.stringify({ frames: PASS_FRAME_URLS, framesSm: PASS_FRAME_SM_URLS }).replace(/</g, "\\u003c");

/**
 * The icon to show for someone whose plan may have ended: a Pass emote they can no longer use falls back
 * to the regular version of the same character (or initials when `baseUnlocked` says it's locked).
 */
export function shownIcon(iconId: string | null | undefined, tier: string | null | undefined, baseUnlocked: (id: string) => boolean = () => true) {
  if (!iconId || !isPassIcon(iconId) || passIconAllowed(iconId, tier)) return iconId ?? null;
  const base = passIcon(iconId)!.character;
  return baseUnlocked(base) ? base : null;
}

/** Emote picker data for the Rewards page, grouped by character. */
export function passPicker(tier: string | null | undefined, frame = true) {
  return {
    tier: isPassTier(tier) ? tier : null,
    frame: frame && isPassTier(tier) ? PASS_FRAME_URLS[tier] : null,
    emotes: PASS_EMOTES.map((e) => ({ id: e.id, name: e.name, ultimate: e.ultimate })),
    characters: ICONS.map((i) => ({
      id: i.id,
      name: i.name,
      emotes: PASS_EMOTES.map((e) => {
        const id = `${i.id}-${e.id}`;
        return { id, name: e.name, ultimate: e.ultimate, unlocked: passIconAllowed(id, tier) };
      }),
    })),
  };
}

/** Add the Pass emote URLs to a ported page's data-icons map. */
export function withPassIconUrls(html: string) {
  return html.replace(/data-icons='(\{[^']*\})'/g, (m, json: string) => {
    try {
      return `data-icons='${JSON.stringify({ ...JSON.parse(json), ...PASS_ICON_URLS })}'`;
    } catch {
      return m;
    }
  });
}
